cat >> src/board.test.ts <<'EOF'

import { createBoard, type BoardErrorCode, type BoardOptions } from "./board";

function setup(columns: BoardOptions["columns"] = [
  { name: "Backlog" }, { name: "Doing" }, { name: "Review" }, { name: "Done" },
]) {
  const clock = { t: 1000 };
  const board = createBoard({ columns, now: () => clock.t });
  return { board, clock };
}

function expectCode(fn: () => unknown, code: BoardErrorCode) {
  try {
    fn();
  } catch (e) {
    expect(e).toBeInstanceOf(BoardError);
    expect((e as BoardError).code).toBe(code);
    return;
  }
  throw new Error(`expected BoardError ${code}`);
}

test("addCard returns sequential ids and appends to the first column", () => {
  const { board } = setup();
  expect(board.addCard("a")).toBe("C1");
  expect(board.addCard("b")).toBe("C2");
  expect(board.cardsIn("Backlog")).toEqual(["C1", "C2"]);
  expect(board.cardsIn("Doing")).toEqual([]);
});
EOF
bun test 2>&1 | tail -5

cat >> src/board.test.ts <<'EOF'

test("addCard fails when the first column is at its WIP limit", () => {
  const { board } = setup([{ name: "Backlog", wipLimit: 2 }, { name: "Done" }]);
  board.addCard("a");
  board.addCard("b");
  expectCode(() => board.addCard("c"), "WIP_LIMIT");
  expect(board.cardsIn("Backlog")).toEqual(["C1", "C2"]);
});
EOF
bun test 2>&1 | grep -E "pass|fail" | tail -2
